using System;using System.IO;using System.Text;using System.Linq;using System.Drawing;using System.Windows.Forms;using System.Text.RegularExpressions;
sealed class SignatureDesigner:Form {
 readonly Companion owner;readonly WebBrowser preview=new WebBrowser{Dock=DockStyle.Fill,ScriptErrorsSuppressed=true,AllowWebBrowserDrop=false,IsWebBrowserContextMenuEnabled=false,WebBrowserShortcutsEnabled=false};readonly RichTextBox source=new RichTextBox{Dock=DockStyle.Fill,Font=new Font("Consolas",10)};readonly TextBox[] fields=new TextBox[8];readonly ComboBox style=new ThemeComboBox{DropDownStyle=ComboBoxStyle.DropDownList,Width=300};readonly CheckBox divider=new CheckBox{Text="Show divider",Checked=true,AutoSize=true};readonly ThemeNumber logoSize=new ThemeNumber{Minimum=24,Maximum=240,Value=80,Width=90};readonly Label status=new Label{Dock=DockStyle.Bottom,Height=35};readonly System.Windows.Forms.Timer timer=new System.Windows.Forms.Timer{Interval=350};string localImage;bool loading;
 internal SignatureDesigner(Companion parent){owner=parent;Text="Email signature · design & preview";Size=new Size(1050,760);MinimumSize=new Size(850,620);Font=parent.Font;Icon=parent.Icon;StartPosition=FormStartPosition.CenterParent;var split=new SplitContainer{Dock=DockStyle.Fill,Size=new Size(1000,650),SplitterDistance=350,Panel1MinSize=300,Panel2MinSize=380};var column=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(12)};column.Controls.Add(new Label{Text="Style",AutoSize=true});style.Items.AddRange(new object[]{"Clean vertical","Horizontal card","Minimal type","Creative banner"});style.SelectedIndex=0;column.Controls.Add(style);string[] names={"Name","Role / business","Email","Phone","Website (https://)","Logo URL (https://, optional)","Accent colour","Extra line / tagline"};for(int i=0;i<names.Length;i++){column.Controls.Add(new Label{Text=names[i],AutoSize=true,Margin=new Padding(0,8,0,2)});fields[i]=new TextBox{Width=300};column.Controls.Add(fields[i]);}fields[0].Text="Your name";fields[1].Text="Creative professional";fields[6].Text="#486d6e";var img=new Button{Text="Add local logo / image…",AutoSize=true};img.Click+=(s,e)=>{using(var pick=new OpenFileDialog{Filter="Images (*.png;*.jpg;*.jpeg)|*.png;*.jpg;*.jpeg"})if(pick.ShowDialog(this)==DialogResult.OK){if(new FileInfo(pick.FileName).Length>2000000){status.Text="Choose an image under 2 MB.";return;}try{using(var image=Image.FromFile(pick.FileName)){double scale=Math.Min(1,480.0/Math.Max(image.Width,image.Height));using(var thumb=new Bitmap(Math.Max(1,(int)(image.Width*scale)),Math.Max(1,(int)(image.Height*scale))))using(var g=Graphics.FromImage(thumb))using(var stream=new MemoryStream()){g.DrawImage(image,0,0,thumb.Width,thumb.Height);thumb.Save(stream,System.Drawing.Imaging.ImageFormat.Png);localImage="data:image/png;base64,"+Convert.ToBase64String(stream.ToArray());}}Build();status.Text="Local image embedded. Some email apps prefer a hosted HTTPS logo.";}catch(Exception ex){status.Text=ex.Message;}}};column.Controls.Add(img);var remove=new Button{Text="Remove image",AutoSize=true};remove.Click+=(s,e)=>{localImage=null;fields[5].Clear();Build();};column.Controls.Add(remove);column.Controls.Add(new Label{Text="Image width (pixels)",AutoSize=true});column.Controls.Add(logoSize);column.Controls.Add(divider);var colour=new Button{Text="Choose accent…",AutoSize=true};colour.Click+=(s,e)=>{var picked=owner.PickColour(this,ColorTranslator.FromHtml(fields[6].Text));if(picked.HasValue)fields[6].Text=ColorTranslator.ToHtml(picked.Value);};column.Controls.Add(colour);split.Panel1.Controls.Add(column);var tabs=new ThemeTabs{Dock=DockStyle.Fill};TabPage visual=new TabPage("Live preview"),html=new TabPage("HTML source");visual.Controls.Add(preview);html.Controls.Add(source);tabs.TabPages.Add(visual);tabs.TabPages.Add(html);split.Panel2.Controls.Add(tabs);var bar=new StableToolStrip{Dock=DockStyle.Top,GripStyle=ToolStripGripStyle.Hidden,LayoutStyle=ToolStripLayoutStyle.Flow};Action<string,Action> button=(label,action)=>owner.Add(bar,label,action);button("Copy formatted",()=>{ClipboardTools.Signature(source.Text);status.Text="Copied · paste into your email signature editor";});button("Copy HTML",()=>{Clipboard.SetText(source.Text);status.Text="HTML copied";});button("Save HTML…",()=>{using(var pick=new SaveFileDialog{Filter="HTML (*.html)|*.html",FileName="Email-signature.html"})if(pick.ShowDialog(this)==DialogResult.OK){Store.Atomic(pick.FileName,source.Text);status.Text="Saved · "+pick.FileName;}});button("Open HTML…",()=>{using(var pick=new OpenFileDialog{Filter="HTML (*.html;*.htm)|*.html;*.htm"})if(pick.ShowDialog(this)==DialogResult.OK){if(new FileInfo(pick.FileName).Length>1000000){status.Text="Choose HTML under 1 MB.";return;}source.Text=File.ReadAllText(pick.FileName);tabs.SelectedTab=html;status.Text="Custom HTML · changing builder fields replaces this design.";}});button("Save preset…",SavePreset);button("Load preset…",LoadPreset);button("Refresh preview",RenderPreview);Controls.Add(split);Controls.Add(status);Controls.Add(bar);foreach(var field in fields)field.TextChanged+=(s,e)=>{if(!loading)Build();};style.SelectedIndexChanged+=(s,e)=>Build();divider.CheckedChanged+=(s,e)=>Build();logoSize.ValueChanged+=(s,e)=>Build();source.TextChanged+=(s,e)=>{timer.Stop();timer.Start();};timer.Tick+=(s,e)=>{timer.Stop();RenderPreview();};preview.Navigating+=(s,e)=>{if(e.Url!=null&&e.Url.ToString()!="about:blank")e.Cancel=true;};FormClosed+=(s,e)=>timer.Dispose();owner.DialogChrome(this);owner.ThemeControls(this);Build();status.Text="Adjust the design on the left. The preview updates here. Test the copied signature in your email app.";}
 internal static string Sanitise(string html){html=Regex.Replace(html,@"<(script|iframe|object|embed|form|style|link|meta|base)\b[^>]*>[\s\S]*?</\1\s*>","",RegexOptions.IgnoreCase);html=Regex.Replace(html,@"<(script|iframe|object|embed|form|link|meta|base)\b[^>]*>","",RegexOptions.IgnoreCase);html=Regex.Replace(html,@"\s+on[a-z]+\s*=\s*(""[^""]*""|'[^']*'|[^\s>]+)","",RegexOptions.IgnoreCase);html=Regex.Replace(html,@"(javascript|vbscript)\s*:","",RegexOptions.IgnoreCase);html=Regex.Replace(html,@"(expression\s*\(|behavior\s*:|-moz-binding\s*:)","",RegexOptions.IgnoreCase);return html;}
 void RenderPreview(){string paper=ColorTranslator.ToHtml(CompanionPalette.For(owner.store.Pref.Theme)[1]);preview.DocumentText="<!doctype html><html><head><meta charset='utf-8'></head><body style='background:"+paper+";padding:24px;font-family:Arial'><div style='background:#fff;display:inline-block;max-width:100%;padding:28px;border-radius:8px'>"+Sanitise(source.Text)+"</div></body></html>";}
 void Build(){if(loading)return;string c=Regex.IsMatch(fields[6].Text,@"^#[0-9a-fA-F]{6}$")?fields[6].Text:"#486d6e",image=localImage;Uri url;if(image==null&&Uri.TryCreate(fields[5].Text,UriKind.Absolute,out url)&&url.Scheme=="https")image=url.AbsoluteUri;string logo=image==null?"":"<img src='"+Store.Html(image)+"' width='"+logoSize.Value+"' style='display:block;width:"+logoSize.Value+"px;height:auto' alt=''>",contact=String.Join("<br>",new[]{fields[2].Text,fields[3].Text,fields[4].Text}.Where(x=>!String.IsNullOrWhiteSpace(x)).Select(Store.Html));string text="<strong style='font-size:20px;color:"+c+"'>"+Store.Html(fields[0].Text)+"</strong><br>"+Store.Html(fields[1].Text)+"<br>"+contact+(fields[7].Text.Length>0?"<br><span style='color:"+c+"'>"+Store.Html(fields[7].Text)+"</span>":"");string rule=divider.Checked?"border-left:3px solid "+c+";":"",body;if(style.SelectedIndex==1)body="<tr><td style='padding-right:18px'>"+logo+"</td><td style='"+rule+"padding-left:18px'>"+text+"</td></tr>";else if(style.SelectedIndex==2)body="<tr><td>"+text+(logo.Length>0?"<br>"+logo:"")+"</td></tr>";else if(style.SelectedIndex==3)body="<tr><td style='padding:16px;background:"+c+"'>"+logo+"</td></tr><tr><td style='padding:16px;"+(divider.Checked?"border-bottom:3px solid "+c+";":"")+"'>"+text+"</td></tr>";else body="<tr><td style='padding-bottom:16px'>"+logo+"</td></tr><tr><td style='padding-top:12px;"+(divider.Checked?"border-top:2px solid "+c+";":"")+"'>"+text+"</td></tr>";source.Text="<table cellpadding='0' cellspacing='0' role='presentation' style='font:14px/1.5 Arial,sans-serif;color:#27363a'>"+body+"</table>";RenderPreview();}
 void SavePreset(){using(var pick=new SaveFileDialog{Filter="Signature preset (*.jagosignature)|*.jagosignature",InitialDirectory=Path.Combine(owner.store.Home,"Templates"),FileName="My signature.jagosignature"})if(pick.ShowDialog(this)==DialogResult.OK)Store.Atomic(pick.FileName,Store.Json.Serialize(new{version=1,fields=fields.Select(x=>x.Text).ToArray(),style=style.SelectedIndex,divider=divider.Checked,width=(int)logoSize.Value,image=localImage,html=source.Text}));}
 void LoadPreset(){using(var pick=new OpenFileDialog{Filter="Signature preset (*.jagosignature)|*.jagosignature",InitialDirectory=Path.Combine(owner.store.Home,"Templates")})if(pick.ShowDialog(this)==DialogResult.OK){if(new FileInfo(pick.FileName).Length>4000000)throw new Exception("Choose a preset under 4 MB.");var data=Store.Json.Deserialize<Preset>(File.ReadAllText(pick.FileName));if(data.version!=1||data.fields==null||data.fields.Length!=8)throw new Exception("Unsupported signature preset.");loading=true;for(int i=0;i<8;i++)fields[i].Text=data.fields[i];style.SelectedIndex=Math.Max(0,Math.Min(3,data.style));divider.Checked=data.divider;logoSize.Value=Math.Max(24,Math.Min(240,data.width));localImage=data.image;loading=false;Build();if(data.html!=null)source.Text=data.html;RenderPreview();}}
 sealed class Preset{public int version{get;set;}public int style{get;set;}public int width{get;set;}public bool divider{get;set;}public string[] fields{get;set;}public string image{get;set;}public string html{get;set;}}
}
